import{_ as n,o as i,c as t,a3 as r}from"./chunks/framework.BvvarXmc.js";const p=JSON.parse('{"title":"Panduan Siswa & Orang Tua (Wali Murid)","description":"","frontmatter":{},"headers":[],"relativePath":"panduan-siswa/index.md","filePath":"panduan-siswa/index.md","lastUpdated":null}'),e={name:"panduan-siswa/index.md"};function s(u,a,d,l,o,g){return i(),t("div",null,[...a[0]||(a[0]=[r('<h1 id="panduan-siswa-orang-tua-wali-murid" tabindex="-1">Panduan Siswa &amp; Orang Tua (Wali Murid) <a class="header-anchor" href="#panduan-siswa-orang-tua-wali-murid" aria-label="Permalink to &quot;Panduan Siswa &amp; Orang Tua (Wali Murid)&quot;">​</a></h1><p>Selamat datang di Portal Siswa <strong>Super Schools</strong>! Melalui portal ini, siswa dan orang tua dapat memantau seluruh aktivitas sekolah dari genggaman gawai (HP) atau laptop secara mandiri dan transparan.</p><hr><h2 id="kemudahan-untuk-siswa-orang-tua" tabindex="-1">Kemudahan untuk Siswa &amp; Orang Tua <a class="header-anchor" href="#kemudahan-untuk-siswa-orang-tua" aria-label="Permalink to &quot;Kemudahan untuk Siswa &amp; Orang Tua&quot;">​</a></h2><ul><li><strong>Cek Tagihan &amp; Bayar SPP Online</strong>: Cek tagihan tanpa perlu antre ke sekolah, bayar lewat transfer Virtual Account ATM/m-Banking dari rumah.</li><li><strong>Kartu Dompet Digital Siswa</strong>: Pantau saldo uang jajan anak di kantin sekolah dan riwayat transaksi belanja.</li><li><strong>Ujian Online &amp; Materi Tugas</strong>: Ikuti ujian sekolah (CBT) dan unduh modul pelajaran kapan saja.</li><li><strong>Pantau Kehadiran Anak</strong>: Orang tua dapat langsung memantau apakah anak hadir di sekolah setiap harinya.</li></ul><hr><h2 id="daftar-panduan-di-bagian-ini" tabindex="-1">Daftar Panduan di Bagian Ini <a class="header-anchor" href="#daftar-panduan-di-bagian-ini" aria-label="Permalink to &quot;Daftar Panduan di Bagian Ini&quot;">​</a></h2><ol><li><strong><a href="/panduan-siswa/login-portal">Panduan Login Pertama Kali</a></strong>: Cara masuk menggunakan NISN dan mengganti password demi keamanan.</li><li><strong><a href="/panduan-siswa/cek-bayar-spp">Cara Cek &amp; Bayar Tagihan SPP</a></strong>: Langkah memilih tagihan, mendapatkan nomor Virtual Account, dan menyimpan bukti bayar resmi.</li><li><strong><a href="/panduan-siswa/mengikuti-ujian-cbt">Tata Cara Mengikuti Ujian CBT</a></strong>: Petunjuk memulai ujian, menjawab soal, dan mengirim jawaban sampai selesai.</li><li><strong><a href="/panduan-siswa/dompet-kartu-siswa">Saldo Kartu Pelajar &amp; Riwayat Jajan</a></strong>: Cara top-up saldo kartu pelajar dan mengatur batas jajan anak di sekolah.</li></ol>',8)])])}const h=n(e,[["render",s]]);export{p as __pageData,h as default};
